import{_ as e,a as r,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Nacos：对象、生命周期与一致性模型","description":"按真实对象和状态变化组织 Nacos 的入门机制。","frontmatter":{"title":"Nacos：对象、生命周期与一致性模型","description":"按真实对象和状态变化组织 Nacos 的入门机制。","showdocs":{"topics":[{"id":"nacos","title":"Nacos","link":"/topics/nacos/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"Nacos协调理论课程","summary":"按真实对象和状态变化组织 Nacos 的入门机制。","status":"active","related":[{"title":"Nacos 完整配置读取与注册项目","link":"/middleware/service-discovery/nacos/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"Nacos：排障、恢复与场景自检","link":"/middleware/service-discovery/nacos/operations","kind":"问题排查","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Nacos 完整配置读取与注册项目","link":"/middleware/service-discovery/nacos/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Nacos 完整配置读取与注册项目","link":"/middleware/service-discovery/nacos/plus/practice/application"}},"headers":[],"relativePath":"middleware/service-discovery/nacos/model.md","filePath":"middleware/service-discovery/nacos/model.md"}'),s={name:"middleware/service-discovery/nacos/model.md"};function n(c,a,p,i,l,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="nacos-对象、生命周期与一致性模型" tabindex="-1">Nacos：对象、生命周期与一致性模型 <a class="header-anchor" href="#nacos-对象、生命周期与一致性模型" aria-label="Permalink to &quot;Nacos：对象、生命周期与一致性模型&quot;">​</a></h1><h2 id="part-1" tabindex="-1">Nacos 服务命名与配置入门 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;Nacos 服务命名与配置入门 {#part-1}&quot;">​</a></h2><h3 id="part-1-environment" tabindex="-1">明确教学版本 <a class="header-anchor" href="#part-1-environment" aria-label="Permalink to &quot;明确教学版本 {#part-1-environment}&quot;">​</a></h3><p>Nacos 版本协议 本课程固定 Nacos Server 2.4.x 与 nacos-client 2.4.3、JDK 17、Maven 3.9，只讨论这一组合的 Java API，不使用 latest 作为隐含依赖。核对日期 2026-10-17。2.x SDK 引入 gRPC，读者除了 HTTP 地址还需正确配置对应客户端 gRPC 连通性；不能只测 8848 HTTP 正常就判定 SDK 通信正常。具体补丁部署与安全维护需读者另外核对，不因本文固定教学坐标而承诺旧版本适合新生产。</p><p>Nacos 3.x 已区分客户端、管理和控制台接口；不能把 2.4 的 <code>/nacos/v1/...</code> 运维脚本直接改个主机名当成 3.x 用法。即使部分兼容行为存在，也应按目标版本正式接口、鉴权和客户端兼容表重新设计。本文不提供 3.x HTTP 实现，避免把协议族混写。</p><p>所有示例未执行，本轮不安装依赖、不启动服务、不连接账号。后文命令仅给读者在自行准备的授权实验环境阅读和运行。</p><h3 id="part-1-roles" tabindex="-1">两种中心的职责 <a class="header-anchor" href="#part-1-roles" aria-label="Permalink to &quot;两种中心的职责 {#part-1-roles}&quot;">​</a></h3><p>Nacos 服务配置 区别在于服务发现返回可用实例，配置中心返回配置文本。服务存在不意味着 reader.properties 已发布；配置可读也不意味着 notes-reader 有健康实例。二者可能使用同一 serverAddr 和 namespace 属性，但权限与业务对象分开管理。应用启动时应分别判定“依赖配置可用”和“服务可以对外接流量”。</p><h3 id="part-1-namespace" tabindex="-1">命名隔离 <a class="header-anchor" href="#part-1-namespace" aria-label="Permalink to &quot;命名隔离 {#part-1-namespace}&quot;">​</a></h3><p>Nacos 命名空间 隔离 要使用 namespace ID，不是控制台显示名。配置标识由 namespace、group、dataId 共同构成；本例 group=NOTES、dataId=reader.properties。服务标识也受 namespace 与 group 约束，cluster 是实例分组维度，不能把 cluster 当 namespace。两个环境使用相同 serviceName，但 namespace 不同，仍是独立发现集合。</p><p>namespace 是逻辑隔离维度，并不自动代替鉴权。把生产 namespace ID 改为测试值只能改变目标范围；如果身份仍拥有全局写权限，权限风险没有消失。示例要求显式提供 ID，避免空字符串默认空间造成误写。</p><h3 id="part-1-commands" tabindex="-1">入门命令与练习 <a class="header-anchor" href="#part-1-commands" aria-label="Permalink to &quot;入门命令与练习 {#part-1-commands}&quot;">​</a></h3><p>Nacos 命令入口 本课使用 Maven 执行独立 Java 项目而非旧 curl OpenAPI；完整命令见<a href="/middleware/service-discovery/nacos/plus/practice/application#run">应用篇</a>。读者先在自己的测试 namespace 中准备 reader.properties，内容为 request.limit=20，再使用只有目标配置读取与实验服务写入权限的身份。</p><p>题目：控制台显示“测试”，为何 SDK 查不到配置？参考答案：检查 namespace ID、group 与 dataId 是否逐项一致，以及配置是否在该空间发布；显示名不是 ID。题目：8848 可访问但 SDK 报连接失败，先看什么？答：目标 serverAddr、端口映射、客户端 gRPC 链路与版本，不先改配置文本。</p><p>中英文检索词为“Nacos 2.4 命名空间 临时实例 灰度 鉴权”与“Nacos 2.4 Java SDK config namespace ephemeral”。最终依据为官方 <a href="https://nacos.io/docs/v2.4/manual/user/java-sdk/usage/" target="_blank" rel="noopener noreferrer">2.4 SDK</a>、<a href="https://nacos.io/docs/v2.4/guide/user/auth/" target="_blank" rel="noopener noreferrer">2.4 鉴权</a> 与 <a href="https://www.nacos.io/en/docs/v3.0/manual/user/open-api/" target="_blank" rel="noopener noreferrer">3.0 客户端接口</a>，最后一项只用于界定跨版本边界。</p><h2 id="part-2" tabindex="-1">Nacos 实例生命周期与配置发布机制 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;Nacos 实例生命周期与配置发布机制 {#part-2}&quot;">​</a></h2><h3 id="part-2-instances" tabindex="-1">临时与持久实例 <a class="header-anchor" href="#part-2-instances" aria-label="Permalink to &quot;临时与持久实例 {#part-2-instances}&quot;">​</a></h3><p>Nacos 临时持久 实例 的区别首先是生命周期与健康维护方式。临时实例适合跟随客户端连接活性的动态进程，2.x Java SDK 通过连接管理注册关系；持久实例更适合显式维护的稳定对象，不因某个注册客户端连接断开就按临时注册关系删除。不要把 1.x HTTP 心跳模型机械套给 2.x gRPC 客户端，也不要以为 persistent 意味着服务永远 healthy。</p><p>临时实例通常走偏可用的分布式注册机制，持久实例元数据使用一致性协议维护；这不表示读者能简单给整个 Nacos 贴 AP 或 CP 单标签。应先说清服务发现对象、实例类型和故障下要维持的合同。示例 setEphemeral(true)，只演示客户端生命周期；没有给持久实例强行添加客户端心跳脚本。</p><h3 id="part-2-health" tabindex="-1">健康快照 <a class="header-anchor" href="#part-2-health" aria-label="Permalink to &quot;健康快照 {#part-2-health}&quot;">​</a></h3><p>Nacos 健康发现 selectInstances(..., true) 取得健康实例快照；注册调用返回后，订阅、本地缓存和集群传播仍有时序，不能保证下一条查询立刻包含新实例。应用拿到地址仍须设置业务连接超时和重试，不能把健康标记视为端到端服务证明。实例 enabled、weight、healthy 与 metadata 作用不同，不能用 weight=0 假装注销并期待所有消费者同样处理。</p><h3 id="part-2-config" tabindex="-1">配置修订与灰度 <a class="header-anchor" href="#part-2-config" aria-label="Permalink to &quot;配置修订与灰度 {#part-2-config}&quot;">​</a></h3><p>Nacos 配置版本 需要区分配置内容摘要、历史修订和业务版本字段。MD5 可用于判断内容是否相同或作 CAS 条件，但它不是可比较大小的单调序号。两位发布者都基于同一旧摘要编辑时，应使用目标版本支持的 CAS 发布接口或外部发布流水线串行化，冲突后重新读取并合并，不能以“最后一次发布成功”掩盖覆盖。</p><p>Nacos 配置灰度 在 2.4 的 beta 发布场景可以针对指定客户端 IP 下发不同内容；它是配置分发范围控制，不是服务实例流量权重，也不是整个业务事务灰度。正式配置与 beta 内容可能并存，排查需记录客户端实际识别地址、命名空间、group、dataId、内容摘要与灰度状态。读者升级到 3.x 后应重新核对灰度模型与管理接口，不延用旧请求参数作为保证。</p><p>发布成功不等于业务接受。应用应先把新文本解析成临时对象，校验字段和约束，再原子替换内存引用；校验失败保留上个有效版本并告警。只在 listener 回调里覆盖全局字符串，会让格式错误直接进入运行路径。示例一次读取并校验正整数，不实现动态监听与发布，避免把最小项目说成完整配置平台。</p><h3 id="part-2-auth" tabindex="-1">认证与授权 <a class="header-anchor" href="#part-2-auth" aria-label="Permalink to &quot;认证与授权 {#part-2-auth}&quot;">​</a></h3><p>Nacos 鉴权身份 需要同时考虑服务端启用鉴权、客户端提供 username/password 和角色资源授权。namespace 隔离不是凭据检查，知道 ID 不能推导访问权限。默认插件不是完整企业身份系统；token 有有效期，应用应让匹配版本 SDK 管理认证过程，不把一次手工获取的 token 永久写入配置。服务端节点间身份与 token 签名密钥属于运维配置，不能以示例公开值当生产秘密。</p><p>练习：测试空间同名配置与生产内容不同，如何定位？参考答案：比对三元组和客户端实际内容摘要，再看 beta 受众与本地缓存；不要只截图控制台配置名。题目：把临时实例改为持久实例能否修复网络断连？答：不能，它改变数据生命周期，不修复链路或客户端协议。</p><p>适用 2.4.x，核对 2026-10-17；官方 <a href="https://nacos.io/docs/v2.4/manual/user/java-sdk/usage/" target="_blank" rel="noopener noreferrer">SDK</a>、<a href="https://nacos.io/docs/v2.4/guide/user/open-api/" target="_blank" rel="noopener noreferrer">OpenAPI 配置接口</a> 与 <a href="https://nacos.io/docs/v2.4/guide/user/auth/" target="_blank" rel="noopener noreferrer">鉴权说明</a> 为核对来源。</p><p>本页为理论说明，关联示例未执行；没有连接服务或验证分布式时序。</p>',30)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
